supabase_bootstrap_sql:
-- Registry Commit v1 — review in a dedicated Supabase development project before production.
create schema if not exists private;

create table if not exists public.fleet_vessels (
  project_id text primary key, namespace text not null unique, display_name text not null,
  lifecycle_state text not null default 'commissioning', created_by_user_id uuid, created_by_role text not null,
  created_at timestamptz not null default now()
);
create table if not exists public.fleet_memberships (
  membership_id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade,
  project_id text not null references public.fleet_vessels(project_id) on delete cascade, role text not null, status text not null default 'active',
  invited_by_user_id uuid, accepted_at timestamptz, revoked_at timestamptz, created_at timestamptz not null default now(),
  unique(user_id, project_id, role)
);
create index if not exists fleet_memberships_user_id_idx on public.fleet_memberships(user_id);
create index if not exists fleet_memberships_project_id_idx on public.fleet_memberships(project_id);

create table if not exists public.fleet_platform_roles (
  platform_role_id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade,
  role text not null check (role in ('admiral','captain','engine_admin')), status text not null default 'active',
  granted_by_user_id uuid, created_at timestamptz not null default now(), revoked_at timestamptz, unique(user_id, role)
);
create index if not exists fleet_platform_roles_user_id_idx on public.fleet_platform_roles(user_id);

create table if not exists public.fleet_authority_events (
  event_id uuid primary key default gen_random_uuid(), actor_user_id uuid, actor_role text not null, project_id text,
  action text not null, result text not null, detail jsonb not null default '{}'::jsonb, created_at timestamptz not null default now()
);
create index if not exists fleet_authority_events_project_id_idx on public.fleet_authority_events(project_id);
create index if not exists fleet_authority_events_actor_user_id_idx on public.fleet_authority_events(actor_user_id);

create table if not exists public.fleet_owner_migrations (
  project_id text primary key references public.fleet_vessels(project_id) on delete cascade, legacy_owner_ref text, production_user_id uuid references auth.users(id),
  status text not null default 'not_started', started_at timestamptz, verified_at timestamptz, rollback_available boolean not null default true
);

alter table public.fleet_vessels enable row level security;
alter table public.fleet_memberships enable row level security;
alter table public.fleet_platform_roles enable row level security;
alter table public.fleet_authority_events enable row level security;
alter table public.fleet_owner_migrations enable row level security;

revoke all on table public.fleet_vessels, public.fleet_memberships, public.fleet_platform_roles, public.fleet_authority_events, public.fleet_owner_migrations from anon, authenticated;
grant select on public.fleet_vessels to authenticated;
grant select on public.fleet_memberships to authenticated;
grant select on public.fleet_platform_roles to authenticated;
grant select on public.fleet_authority_events to authenticated;

create policy "member reads exact vessel" on public.fleet_vessels for select to authenticated
using (exists (select 1 from public.fleet_memberships m where m.user_id=(select auth.uid()) and m.project_id=fleet_vessels.project_id and m.status='active'));
create policy "member reads own memberships" on public.fleet_memberships for select to authenticated
using (user_id=(select auth.uid()));
create policy "user reads own platform roles" on public.fleet_platform_roles for select to authenticated
using (user_id=(select auth.uid()));
create policy "member reads vessel authority events" on public.fleet_authority_events for select to authenticated
using (project_id is not null and exists (select 1 from public.fleet_memberships m where m.user_id=(select auth.uid()) and m.project_id=fleet_authority_events.project_id and m.status='active'));

-- Writes that create vessels, grant/revoke platform roles, transfer ownership, or mutate membership are server-only Edge Function operations.
-- The browser receives no insert/update/delete grants for these authority tables.
